flowchart TD
  A["¿De qué futuro hablas?"] --> B{"¿Es un horario oficial?"}
  B -->|"Sí"| B1["present simple: The train leaves at 8"]
  B -->|"No"| C{"¿Es una cita acordada con alguien, con día y hora?"}
  C -->|"Sí"| C1["present continuous: I'm meeting Ana at 6"]
  C -->|"No"| D{"¿Cuándo lo decidiste?"}
  D -->|"Antes de hablar"| D1["be going to: I'm going to learn Python"]
  D -->|"Ahora mismo"| D2["will: I'll call you back"]
  D -->|"Todavía no lo sé"| D3["might: I might go"]

flowchart TD
  A["¿Qué quieres decir del futuro?"] --> B{"¿Es una decisión o una predicción?"}
  B -->|"Decisión"| C{"¿Cuándo la tomaste?"}
  C -->|"Antes de hablar"| C1["going to: I'm going to buy milk"]
  C -->|"Ahora, al hablar"| C2["will: Oh, I'll buy some milk"]
  B -->|"Predicción"| D{"¿Ves una señal concreta ahora?"}
  D -->|"Sí"| D1["going to: Look, it's going to rain"]
  D -->|"No, es mi opinión"| D2["will: I think it'll rain tomorrow"]
  B -->|"No estoy seguro"| E["might: It might rain"]
